mapper.select:
select record_id,patient_id,research_id,follow_id,name,stage_num,
stage_add_num,question_status,warn_status,over_time_status,over_time_handle_status,update_by,create_by,create_time,
update_time,fill_time,fill_status,visit_time,lock_visit_time,evaluate_status,edc_status, follow_tip_status ,is_see_detail ,is_submit,
follow_opinion,follow_status,lose_reason,lose_type
from patient_record

    and research_id not in (select qr.research_id from quit_record qr, patient_info pi
    where qr.research_id = patient_record.research_id and qr.is_agree = 1
    and pi.patient_id = patient_record.patient_id and qr.research_id = pi.research_id
    and pi.person_id = qr.person_id)
     and record_id= #{recordId}
     and patient_id= #{patientId}
     and research_id= #{researchId}
     and follow_id= #{followId}
     and name= #{name}
     and stage_num= #{stageNum}
     and question_status= #{questionStatus}
     and warn_status= #{warnStatus}
     and over_time_status= #{overTimeStatus}
     and over_time_handle_status= #{overTimeHandleStatus}
     and update_by= #{updateBy}
     and create_by= #{createBy}
     and create_time= #{createTime}
     and update_time= #{updateTime}
     and fill_time= #{fillTime}
     and fill_status= #{fillStatus}
     and lose_reason= #{loseReason}
     and visit_time= #{visitTime}
     and lock_visit_time= #{lockVisitTime}
     and evaluate_status= #{evaluateStatus}
     and edc_status= #{edcStatus}
     and follow_tip_status= #{followTipStatus,jdbcType=INTEGER}
     and is_see_detail= #{isSeeDetail}
     and follow_opinion= #{followOpinion}
     and follow_status= #{followStatus}

    order by visit_time desc;

select p.patient_id,p.person_id, p.patient_name, i.project_name, r.name as stage_name, r.create_time, r.record_id, b.phone_number as mobile,r.over_time_handle_status,
r.lose_type,r.lose_reason,r.visit_time  from patient_record r, patient_info p, research_info i, mp_person b
where i.id=p.research_id and p.patient_id=r.patient_id and b.person_id=p.person_id and p.patient_activity_status = '1'
and r.research_id = #{researchId} and i.del_flag = '0'
and r.is_submit = 1
 and r.follow_status = #{followStatus}
 and r.evaluate_status = #{evaluateStatus}
 and r.warn_status = #{warnStatus}
 and r.over_time_status = #{overTimeStatus}
 and p.patient_name  like concat('%', #{searchKey}, '%')
order by r.visit_time desc
LIMIT ${(pageNo-1)*pageSize},${pageSize}

select p.patient_id,p.person_id, p.patient_name, i.project_name, r.name as stage_name, r.create_time, r.record_id, p.patient_mobile mobile,r.over_time_handle_status,
r.lose_type,r.lose_reason,r.visit_time,p.generated_manually  from patient_record r, patient_info p, research_info i, mp_person mp
where i.id=p.research_id and p.patient_id=r.patient_id and mp.person_id=p.person_id and p.patient_activity_status = '1'
and r.research_id = #{researchId} and i.del_flag = '0'
and r.is_submit = 1
 and r.follow_status = #{followStatus}
 and r.evaluate_status = #{evaluateStatus}
 and r.warn_status = #{warnStatus}
 and r.over_time_status = #{overTimeStatus}
 and p.patient_name  like concat('%', #{searchKey}, '%')
order by r.visit_time desc

select p.patient_id,p.person_id, p.patient_name, i.project_name, r.name as stage_name, r.create_time, r.record_id, p.patient_mobile mobile,r.over_time_handle_status,
r.lose_type,r.lose_reason,r.visit_time,r.warn_status  from patient_record r, patient_info p, research_info i,
mp_person b
where i.id=p.research_id and p.patient_id=r.patient_id and b.person_id=p.person_id and p.patient_activity_status = '1'
and r.research_id = #{researchId}
and r.is_submit = 1
 and r.follow_status = #{followStatus}
 and r.evaluate_status = #{evaluateStatus}
 and r.warn_status = #{warnStatus}
 and r.over_time_status = #{overTimeStatus}
 and p.patient_name  like concat('%', #{searchKey}, '%')

mapper.update:
update patient_record
patient_id = #{patientId}, research_id = #{researchId}, follow_id = #{followId}, name = #{name}, stage_num = #{stageNum}, question_status = #{questionStatus}, warn_status = #{warnStatus}, over_time_status = #{overTimeStatus}, over_time_handle_status = #{overTimeHandleStatus}, update_by = #{updateBy}, create_by = #{createBy}, create_time = #{createTime}, update_time = #{updateTime}, follow_submit_time = #{followSubmitTime}, fill_time = #{fillTime}, fill_status = #{fillStatus}, visit_time = #{visitTime}, lock_visit_time = #{lockVisitTime}, evaluate_status = #{evaluateStatus}, evaluate_prescription = #{evaluatePrescription}, evaluate_quality = #{evaluateQuality}, evaluate_reply = #{evaluateReply}, evaluate_reply_time = #{evaluateReplyTime}, edc_status = #{edcStatus}, follow_tip_status = #{followTipStatus,jdbcType=INTEGER}, is_see_detail = #{isSeeDetail,jdbcType=INTEGER}, follow_opinion = #{followOpinion}, follow_status = #{followStatus}, lose_type = #{loseType}, lose_reason = #{loseReason}, follow_opinion_user_id = #{followOpinionUserId}, ignore_type = #{ignoreType}, evaluate_status_back = #{evaluateStatusBack}, follow_complete_time = #{followCompleteTime}, is_submit = #{isSubmit}, over_time_handle_time = #{overTimeHandleTime}, form_complent_rate = #{formComplentRate},
where record_id = #{recordId}

mapper.select:
select count(*) from patient_record r, patient_info p, research_info i, mp_person b
where i.id=p.research_id and p.patient_id=r.patient_id and b.person_id=p.person_id and p.patient_activity_status = '1'
and r.research_id = #{researchId} and i.del_flag = '0'
and r.is_submit = 1
 and r.follow_status = #{followStatus}
 and r.evaluate_status = #{evaluateStatus}
 and r.warn_status = #{warnStatus}
 and r.over_time_status = #{overTimeStatus}

select count(*) from patient_record r, patient_info p, research_info i, mp_person b
where i.id=p.research_id and p.patient_id=r.patient_id and b.person_id=p.person_id and p.patient_activity_status = '1'
and r.research_id = #{researchId} and i.del_flag = '0'
 and r.follow_status = #{followStatus}
 and r.evaluate_status = #{evaluateStatus}
 and r.warn_status = #{warnStatus}
 and r.over_time_status = #{overTimeStatus}

select p.patient_id,p.person_id, p.patient_name, i.project_name, r.name as stage_name, r.create_time, r.record_id, b.phone_number as mobile
from patient_record r, patient_info p, research_info i, mp_person b
where i.id=p.research_id and p.patient_id=r.patient_id and b.person_id=p.person_id
and p.account_id = #{accountId}
and p.research_id not in (select DISTINCT(q.research_id) from quit_record q where q.is_agree = 1 and q.research_id = p.research_id and q.person_id = p.person_id)
 and r.warn_status = #{warnStatus}
 and r.over_time_status = #{overTimeStatus}

select count(*) from patient_record r, patient_info p, research_info i, mp_person b
where i.id=p.research_id and p.patient_id=r.patient_id and b.person_id=p.person_id and p.patient_activity_status = '1'
and  p.account_id = #{accountId}
 and r.warn_status = #{warnStatus}

select p.patient_id,p.person_id, p.patient_name, i.project_name, r.name as stage_name, r.create_time, r.record_id, b.phone_number as mobile,r.over_time_handle_status,
r.lose_type,r.lose_reason,r.visit_time  from patient_record r, patient_info p, research_info i, mp_person b
where i.id=p.research_id and p.patient_id=r.patient_id and b.person_id=p.person_id and p.patient_activity_status = '1'
and r.research_id = #{researchId} and i.del_flag = '0'

 and r.follow_status = #{followStatus}
 and r.evaluate_status = #{evaluateStatus}
 and r.warn_status = #{warnStatus}
 and r.over_time_status = #{overTimeStatus}
 and p.patient_name  like concat('%', #{searchKey}, '%')
order by r.visit_time desc
LIMIT ${(pageNo-1)*pageSize},${pageSize}

select p.patient_id,p.person_id, p.patient_name, i.project_name, r.name as stage_name, r.create_time, r.record_id,
       b.phone_number as mobile,r.over_time_handle_status,r.lose_type,r.lose_reason,r.visit_time
from patient_record r, patient_info p, research_info i, mp_person b ,patient_record_template prt
where i.id=p.research_id and p.patient_id=r.patient_id and b.person_id=p.person_id and prt.follow_id=r.follow_id and prt.follow_num>0
and i.del_flag = '0'
 and r.research_id = #{researchId}
 and r.follow_status = #{followStatus}
 and r.evaluate_status = #{evaluateStatus}
 and r.warn_status = #{warnStatus}
 and r.over_time_status = #{overTimeStatus}
 and p.patient_name  like concat('%', #{searchKey}, '%')
LIMIT ${(pageNo-1)*pageSize},${pageSize}

select count(1)
from patient_record r, patient_info p, research_info i, mp_person b ,patient_record_template prt
where i.id=p.research_id and p.patient_id=r.patient_id and b.person_id=p.person_id and prt.follow_id=r.follow_id and prt.follow_num>0
and r.research_id = #{researchId} and i.del_flag = '0'
 and r.follow_status = #{followStatus}
 and r.evaluate_status = #{evaluateStatus}
 and r.warn_status = #{warnStatus}
 and r.over_time_status = #{overTimeStatus}
 and p.patient_name  like concat('%', #{searchKey}, '%')
